create table outreach_consents(id bigserial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade,contact_id int not null references contacts,channel text not null check(channel in ('sms','whatsapp_call')),granted boolean not null,evidence text not null,actor_id int not null references users,at timestamptz not null default now(),unique(tenant_id,contact_id,channel));
create table outreach_campaigns(id bigserial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade,name text not null,channel text not null check(channel in ('sms','whatsapp_call')),content text not null,config jsonb not null,actor_id int not null references users,state text not null default 'draft',created_at timestamptz not null default now(),next_at timestamptz not null default now());
create table outreach_jobs(id bigserial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade,campaign_id bigint not null references outreach_campaigns,contact_id int not null references contacts,target text not null,state text not null default 'pending',external_id text,error text,at timestamptz,unique(campaign_id,contact_id));
create table outreach_calls(id bigserial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade,conversation_id int not null references conversations,actor_id int not null references users,session_id text not null,request_key text not null,external_id text,state text not null default 'starting',error text,created_at timestamptz not null default now(),unique(tenant_id,request_key));
do $$declare r record;begin for r in select * from(values('outreach_consents','contacts,contact_id,users,actor_id'),('outreach_campaigns','users,actor_id'),('outreach_jobs','outreach_campaigns,campaign_id,contacts,contact_id'),('outreach_calls','conversations,conversation_id,users,actor_id')) v(t,refs) loop execute format('alter table %I enable row level security',r.t);execute format('alter table %I force row level security',r.t);execute format('create policy tenant_iso on %I using(tenant_id=nullif(current_setting(''app.tenant'',true),'''')::int) with check(tenant_id=nullif(current_setting(''app.tenant'',true),'''')::int)',r.t);execute format('create trigger fk_guard before insert or update on %I for each row execute function fk_guard(%s)',r.t,(select string_agg(quote_literal(x),',') from unnest(string_to_array(r.refs,',')) x));end loop;end $$;
create unique index whatsapp_call_session_exclusive on settings((value->>'session_id')) where key='whatsapp_calls' and value->>'enabled'='true';
alter table outreach_jobs add column session_id text;
create table outreach_consent_history(id bigserial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade,contact_id int not null references contacts,channel text not null,granted boolean not null,evidence text not null,actor_id int not null references users,at timestamptz not null default now());
alter table outreach_consent_history enable row level security;alter table outreach_consent_history force row level security;
create policy tenant_iso on outreach_consent_history using(tenant_id=nullif(current_setting('app.tenant',true),'')::int) with check(tenant_id=nullif(current_setting('app.tenant',true),'')::int);
create trigger fk_guard before insert or update on outreach_consent_history for each row execute function fk_guard('contacts','contact_id','users','actor_id');
create function outreach_consent_audit() returns trigger language plpgsql as $$begin insert into outreach_consent_history(contact_id,channel,granted,evidence,actor_id) values(new.contact_id,new.channel,new.granted,new.evidence,new.actor_id);return new;end$$;
create trigger outreach_consent_audit after insert or update on outreach_consents for each row execute function outreach_consent_audit();
